hooks.command:
gjdc_sync() {
  d="$1"; raw=".$1.gjdc-raw.$$"; tmp=".$1.gjdc-tmp.$$";
  if gh api "repos/groupe-j/dev-conventions/contents/$d" --jq '.content' > "$raw" 2>/dev/null && [ -s "$raw" ] && base64 -d < "$raw" > "$tmp" 2>/dev/null && [ -s "$tmp" ]; then
    rm -f "$raw"; mv -f "$tmp" "$d"; return 0;
  fi;
  rm -f "$raw" "$tmp";
  echo "gjdc: echec de synchro de $d — le fichier existant est CONSERVE (ni vide, ni tronque). Verifier gh auth status et le reseau ; les conventions locales peuvent etre PERIMEES." >&2;
  return 1;
};
gjdc_rc=0;
gjdc_sync CLAUDE_SHARED.md || gjdc_rc=1;
exit $gjdc_rc
